/**
 * ЧӨЛӨӨЛӨГДСӨН ТӨЛӨВИЙН ЦОРЫН ГАНЦ УТГА.
 *
 * ⚠️ 2026-09-06-ны шилжилтийн дараа ангилал ХОЁР л болсон: энэ утга, эсвэл
 * түүнээс БУСАД (=чөлөөлөгдөөгүй, шалтгаан нь утга нь өөрөө). Урьд нь код
 * гурван мөрийг («Бүрэн чөлөөлсөн» + «Цэвэрлэсэн…» − «Үлдсэн…») ТАВАН файлд
 * тус тусад нь хатуу бичдэг байсныг энд нэгтгэв — эх өгөгдөл дахин
 * өөрчлөгдвөл нэг л газар засна.
 */
export const PARCEL_CLEARED = 'Бүрэн чөлөөлсөн';

/** «Чөлөөлөгдсөн» SQL нөхцөл */
export const parcelClearedWhere = () =>
  `${PARCEL_LEFT.fields.status} = N'${PARCEL_CLEARED}'`;

/**
 * «ҮЛДСЭН» (чөлөөлөгдөөгүй) SQL нөхцөл.
 * ⚠️ `<>` нь NULL мөрийг ОРУУЛАХГҮЙ тул `IS NULL` салааг ил нэмнэ — эс бөгөөс
 * төлөвгүй мөр хоёр ангилалд ч ороогүй чимээгүй алга болно.
 */
export const parcelLeftWhere = () =>
  `(${PARCEL_LEFT.fields.status} IS NULL OR ${PARCEL_LEFT.fields.status} <> N'${PARCEL_CLEARED}')`;

/**
 * Нэгж талбарын ObjectID-уудын SQL — газрын зургийн шүүлт ба `zoomToWhere`-т.
 * ⚠️ ЗААВАЛ `PARCEL_LEFT.oid` (`FID`) — хатуу «OBJECTID» БИЧИЖ БОЛОХГҮЙ.
 * `Selbe_parcel_20260906/121`-д `OBJECTID` нэртэй ЭНГИЙН Integer багана
 * мөн байгаа бөгөөд БҮХ мөрд утга нь 0 (амьдаар батлагдсан) — тиймээс
 * `OBJECTID IN (…)` нь ҮРГЭЛЖ 0 мөр буцааж, «Саад — багцаар»-аас багц
 * сонгоход давхцсан талбар зурагт ОГТ гарахгүй, зураг ч тэднийг зааж
 * томрохгүй байв. `overlapLeftParcels` нь `returnIdsOnly`-оор давхаргын
 * ЖИНХЭНЭ OID-г (=`FID`) буцаадаг тул энд мөн түүгээр асуух ёстой.
 */
export const parcelOidsWhere = (oids: readonly number[]): string =>
  `${PARCEL_LEFT.oid} IN (${oids.join(',')})`;

